/**
 * eloe-zip.js — lightweight ZIP builder for eloe extension
 * Bundled locally at libs/jszip.min.js (no CDN dependency)
 * Implements ZIP spec: STORE for small files, deflate raw via CompressionStream API
 * Compatible with Chrome MV3 service workers (which have CompressionStream).
 *
 * API is a subset of JSZip so background.js needs no changes:
 *   const zip = new JSZip();
 *   zip.file(name, data);                   // data = ArrayBuffer | Uint8Array | string
 *   const blob = await zip.generateAsync({ type:'blob' });
 */
(function(global) {
  'use strict';

  function u32(n) {
    return new Uint8Array([n & 0xff, (n >> 8) & 0xff, (n >> 16) & 0xff, (n >> 24) & 0xff]);
  }
  function u16(n) {
    return new Uint8Array([n & 0xff, (n >> 8) & 0xff]);
  }

  function crc32(buf) {
    let c = -1;
    for (let i = 0; i < buf.length; i++) {
      c = (c >>> 8) ^ CRC_TABLE[(c ^ buf[i]) & 0xff];
    }
    return (-1 ^ c) >>> 0;
  }

  // Build CRC table
  const CRC_TABLE = new Uint32Array(256);
  for (let i = 0; i < 256; i++) {
    let c = i;
    for (let j = 0; j < 8; j++) c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1);
    CRC_TABLE[i] = c;
  }

  function encodeStr(s) {
    return new TextEncoder().encode(s);
  }

  function toUint8(data) {
    if (data instanceof Uint8Array) return data;
    if (data instanceof ArrayBuffer) return new Uint8Array(data);
    if (typeof data === 'string') return encodeStr(data);
    return new Uint8Array(data);
  }

  // Deflate a Uint8Array using the browser's CompressionStream (raw deflate)
  async function deflate(data) {
    try {
      const cs = new CompressionStream('deflate-raw');
      const writer = cs.writable.getWriter();
      writer.write(data);
      writer.close();
      const chunks = [];
      const reader = cs.readable.getReader();
      for (;;) {
        const { done, value } = await reader.read();
        if (done) break;
        chunks.push(value);
      }
      const total = chunks.reduce((s, c) => s + c.length, 0);
      const out = new Uint8Array(total);
      let off = 0;
      for (const c of chunks) { out.set(c, off); off += c.length; }
      return out;
    } catch (_) {
      return null; // CompressionStream not available, fall back to STORE
    }
  }

  // Concatenate Uint8Arrays
  function concat(...arrays) {
    const total = arrays.reduce((s, a) => s + a.length, 0);
    const out = new Uint8Array(total);
    let off = 0;
    for (const a of arrays) { out.set(a, off); off += a.length; }
    return out;
  }

  // DOS time encoding
  function dosTime() {
    const d = new Date();
    const time = (d.getHours() << 11) | (d.getMinutes() << 5) | (d.getSeconds() >> 1);
    const date = ((d.getFullYear() - 1980) << 9) | ((d.getMonth() + 1) << 5) | d.getDate();
    return { time, date };
  }

  class JSZip {
    constructor() { this._files = []; }

    file(name, data) {
      this._files.push({ name, data });
      return this;
    }

    folder(name) {
      // no-op for compatibility — files use paths directly
      return this;
    }

    async generateAsync({ type = 'blob', compression = 'DEFLATE' } = {}) {
      const useDeflate = compression === 'DEFLATE';
      const localHeaders = [];
      const centralDirs  = [];
      let offset = 0;

      for (const f of this._files) {
        const nameBytes = encodeStr(f.name);
        const rawData   = toUint8(f.data);
        const crc       = crc32(rawData);
        const uncompLen = rawData.length;
        const { time, date } = dosTime();

        let compData = useDeflate ? await deflate(rawData) : null;
        // Use deflated only if it's actually smaller
        let method, compLen, fileData;
        if (compData && compData.length < uncompLen) {
          method = 8; compLen = compData.length; fileData = compData;
        } else {
          method = 0; compLen = uncompLen; fileData = rawData;
        }

        // Local file header
        const lh = concat(
          new Uint8Array([0x50, 0x4b, 0x03, 0x04]), // signature
          u16(20),            // version needed
          u16(0),             // flags
          u16(method),        // compression method
          u16(time), u16(date),
          u32(crc),
          u32(compLen),
          u32(uncompLen),
          u16(nameBytes.length),
          u16(0),             // extra field length
          nameBytes,
          fileData
        );

        // Central directory header
        const cd = concat(
          new Uint8Array([0x50, 0x4b, 0x01, 0x02]),
          u16(20), u16(20),   // version made by, version needed
          u16(0),             // flags
          u16(method),
          u16(time), u16(date),
          u32(crc),
          u32(compLen),
          u32(uncompLen),
          u16(nameBytes.length),
          u16(0),             // extra length
          u16(0),             // comment length
          u16(0),             // disk start
          u16(0),             // internal attrs
          u32(0),             // external attrs
          u32(offset),        // local header offset
          nameBytes
        );

        localHeaders.push(lh);
        centralDirs.push(cd);
        offset += lh.length;
      }

      const centralDirOffset = offset;
      const centralDirData   = concat(...centralDirs);
      const count            = this._files.length;

      // End of central directory record
      const eocd = concat(
        new Uint8Array([0x50, 0x4b, 0x05, 0x06]),
        u16(0), u16(0),                    // disk numbers
        u16(count), u16(count),            // entry counts
        u32(centralDirData.length),
        u32(centralDirOffset),
        u16(0)                             // comment length
      );

      const zipData = concat(...localHeaders, centralDirData, eocd);

      if (type === 'blob')        return new Blob([zipData], { type: 'application/zip' });
      if (type === 'uint8array')  return zipData;
      if (type === 'arraybuffer') return zipData.buffer;
      if (type === 'base64') {
        let s = '';
        for (let i = 0; i < zipData.length; i++) s += String.fromCharCode(zipData[i]);
        return btoa(s);
      }
      return zipData;
    }
  }

  // Export as global JSZip (matches importScripts() usage)
  global.JSZip = JSZip;

})(typeof globalThis !== 'undefined' ? globalThis : typeof self !== 'undefined' ? self : this);
